import React, { useEffect, useState, useCallback } from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';
import { addDoc, collection, getDocs, deleteDoc, doc } from 'firebase/firestore';
import { db } from '../services/firebaseConfig';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/ui/ToastContainer';
import PageContainer, { PageHeader, PageTitle, PageSubtitle } from '../components/PageContainer';

// ============= STYLES =============

const Container = styled(PageContainer)`
  max-width: 100%;
`;

const SummaryCard = styled(motion.div)`
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.2), rgba(59, 130, 246, 0.05));
  border: 1px solid rgba(59, 130, 246, 0.3);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  margin-bottom: var(--space-lg);

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const SummaryContent = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-md);

  @media (min-width: 768px) {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
`;

const SummaryInfo = styled.div``;

const SummaryTitle = styled.h3`
  font-size: var(--fs-lg);
  color: #f8fafc;
  margin-bottom: var(--space-xs);
  font-weight: var(--fw-semibold);
`;

const SummarySubtitle = styled.p`
  font-size: var(--fs-sm);
  color: #93c5fd;
`;

const SummaryValue = styled.div`
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: var(--fw-bold);
  color: #3b82f6;
`;

const FormCard = styled.div`
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid rgba(56, 189, 248, 0.15);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  margin-bottom: var(--space-lg);
  backdrop-filter: blur(8px);

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const SectionTitle = styled.h2`
  font-size: var(--fs-lg);
  color: #38bdf8;
  margin-bottom: var(--space-md);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
`;

const FormGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
`;

const Label = styled.label`
  font-size: var(--fs-sm);
  color: #cbd5e1;
  margin-bottom: var(--space-xs);
  font-weight: var(--fw-medium);
`;

const Input = styled.input`
  background: #1e293b;
  border: 1px solid #334155;
  color: #f8fafc;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  width: 100%;
  font-size: var(--fs-base);
  min-height: 48px;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);

  &:focus {
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
  }

  &::placeholder {
    color: #64748b;
  }
`;

const Button = styled.button`
  background: ${props => props.$variant === 'primary'
    ? 'linear-gradient(135deg, #38bdf8, #0ea5e9)'
    : 'rgba(51, 65, 85, 0.5)'};
  color: ${props => props.$variant === 'primary' ? '#0f172a' : '#f8fafc'};
  border: ${props => props.$variant === 'secondary' ? '1px solid #334155' : 'none'};
  font-weight: var(--fw-semibold);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 48px;
  flex: ${props => props.$block ? '1' : 'none'};
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);

  &:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: ${props => props.$variant === 'primary'
    ? '0 4px 12px rgba(56, 189, 248, 0.4)'
    : 'none'};
  }

  &:active:not(:disabled) {
    transform: scale(0.98);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }

  @media (min-width: 480px) {
    flex: ${props => props.$block ? 'none' : '1'};
    min-width: ${props => props.$block ? 'auto' : '120px'};
  }
`;

const ButtonGroup = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-md);

  @media (min-width: 480px) {
    flex-direction: row;
  }
`;

const ListHeader = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-bottom: var(--space-md);

  @media (min-width: 768px) {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
`;

const ListTitle = styled.h3`
  font-size: var(--fs-lg);
  color: #f8fafc;
  margin: 0;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
`;

const ItemCount = styled.span`
  font-size: var(--fs-sm);
  color: #94a3b8;
`;

const FixedList = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
`;

const EmptyState = styled.div`
  background: rgba(30, 41, 59, 0.5);
  border: 1px solid rgba(148, 163, 184, 0.1);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;

  @media (min-width: 768px) {
    padding: var(--space-2xl);
  }
`;

const EmptyIcon = styled.div`
  font-size: 4rem;
  margin-bottom: var(--space-md);

  @media (min-width: 768px) {
    font-size: 6rem;
  }
`;

const EmptyText = styled.p`
  color: #94a3b8;
  font-size: var(--fs-lg);
  margin-bottom: var(--space-sm);

  @media (min-width: 768px) {
    font-size: var(--fs-base);
  }
`;

const EmptySubtext = styled.p`
  color: #64748b;
  font-size: var(--fs-sm);
`;

const FixedItem = styled(motion.div)`
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  transition: all var(--transition-normal);
  min-height: 88px;

  @media (min-width: 640px) {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }

  &:hover {
    transform: translateY(-2px);
    background: rgba(30, 58, 138, 0.4);
    border-color: #3b82f6;
  }
`;

const ItemLeft = styled.div`
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex: 1;
`;

const ItemIcon = styled.div`
  font-size: 1.5rem;
  flex-shrink: 0;

  @media (min-width: 768px) {
    font-size: 2rem;
  }
`;

const ItemInfo = styled.div`
  flex: 1;
  min-width: 0;
`;

const ItemName = styled.p`
  font-size: var(--fs-base);
  color: #f8fafc;
  font-weight: var(--fw-medium);
  word-break: break-word;

  @media (min-width: 768px) {
    font-size: var(--fs-lg);
  }
`;

const ItemDescription = styled.p`
  font-size: var(--fs-sm);
  color: #94a3b8;
`;

const ItemRight = styled.div`
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-top: var(--space-xs);

  @media (min-width: 640px) {
    margin-top: 0;
  }
`;

const ItemValue = styled.span`
  font-size: var(--fs-lg);
  font-weight: var(--fw-bold);
  color: #3b82f6;

  @media (min-width: 768px) {
    font-size: var(--fs-xl);
  }
`;

const DeleteButton = styled.button`
  background: rgba(51, 65, 85, 0.5);
  color: #f8fafc;
  border: none;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  font-size: var(--fs-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  &:hover {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
  }

  @media (min-width: 480px) {
    padding: var(--space-sm) var(--space-lg);
  }
`;

// ============= MAIN COMPONENT =============

export default function FixedExpenses() {
  const { user } = useAuth();
  const { showSuccess, showError } = useToast();
  const [fixedList, setFixedList] = useState([]);
  const [name, setName] = useState('');
  const [value, setValue] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const loadFixedExpenses = useCallback(async () => {
    if (!user) return;
    const snapshot = await getDocs(collection(db, "users", user.uid, "fixed_expenses"));
    setFixedList(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  }, [user]);

  useEffect(() => {
    loadFixedExpenses();
  }, [loadFixedExpenses]);

  const addFixedExpense = async () => {
    if (!user) {
      showError("Você precisa estar logado para adicionar gastos fixos.");
      return;
    }
    if (!name.trim() || !value) {
      showError('Preencha todos os campos!');
      return;
    }
    setIsAdding(true);
    try {
      await addDoc(collection(db, "users", user.uid, "fixed_expenses"), {
        name: name.trim(),
        value: parseFloat(value)
      });
      setName('');
      setValue('');
      loadFixedExpenses();
      showSuccess('Gasto fixo adicionado com sucesso!');
    } catch (error) {
      console.error('Erro ao adicionar gasto fixo:', error);
      showError('Erro ao adicionar gasto fixo. Tente novamente.');
    } finally {
      setIsAdding(false);
    }
  };

  const removeFixed = async (id) => {
    if (!user) {
      showError("Você precisa estar logado para remover gastos fixos.");
      return;
    }
    if (!window.confirm('Tem certeza que deseja remover este gasto fixo?')) return;
    try {
      await deleteDoc(doc(db, "users", user.uid, "fixed_expenses", id));
      loadFixedExpenses();
      showSuccess('Gasto fixo removido com sucesso!');
    } catch (error) {
      console.error('Erro ao remover gasto fixo:', error);
      showError('Erro ao remover gasto fixo. Tente novamente.');
    }
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  const totalFixedExpenses = fixedList.reduce((acc, item) => acc + parseFloat(item.value || 0), 0);

  const renderList = () => {
    if (fixedList.length === 0) {
      return (
        <EmptyState>
          <EmptyIcon>🏠</EmptyIcon>
          <EmptyText>Nenhum gasto fixo cadastrado ainda.</EmptyText>
          <EmptySubtext>Adicione seu primeiro gasto fixo acima!</EmptySubtext>
        </EmptyState>
      );
    }

    return (
      <FixedList>
        {fixedList.map((item, index) => (
          <FixedItem
            key={item.id}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.1 * index }}
            whileHover={{ scale: 1.02 }}
          >
            <ItemLeft>
              <ItemIcon>🏠</ItemIcon>
              <ItemInfo>
                <ItemName>{item.name}</ItemName>
                <ItemDescription>Gasto mensal recorrente</ItemDescription>
              </ItemInfo>
            </ItemLeft>
            <ItemRight>
              <ItemValue>{formatCurrency(item.value)}</ItemValue>
              <DeleteButton
                onClick={() => removeFixed(item.id)}
                aria-label="Remover gasto fixo"
              >
                🗑️
              </DeleteButton>
            </ItemRight>
          </FixedItem>
        ))}
      </FixedList>
    );
  };

  return (
    <Container>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <PageHeader style={{ marginBottom: 'var(--space-lg)' }}>
          <div>
            <PageTitle>
              💼 Gastos Fixos
            </PageTitle>
            <PageSubtitle>
              Controle seus gastos mensais recorrentes
            </PageSubtitle>
          </div>
        </PageHeader>

        {/* Resumo */}
        <SummaryCard
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <SummaryContent>
            <SummaryInfo>
              <SummaryTitle>Total de Gastos Fixos</SummaryTitle>
              <SummarySubtitle>{fixedList.length} itens cadastrados</SummarySubtitle>
            </SummaryInfo>
            <SummaryValue>
              {formatCurrency(totalFixedExpenses)}
            </SummaryValue>
          </SummaryContent>
        </SummaryCard>

        {/* Formulário de Adição */}
        <FormCard>
          <SectionTitle>
            ➕ Novo Gasto Fixo
          </SectionTitle>

          <FormGrid>
            <FormGroup>
              <Label>Nome do Gasto</Label>
              <Input
                type="text"
                placeholder="Ex: Aluguel, Conta de Luz..."
                value={name}
                onChange={(e) => setName(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && addFixedExpense()}
              />
            </FormGroup>

            <FormGroup>
              <Label>Valor Mensal (R$)</Label>
              <Input
                type="number"
                placeholder="0,00"
                step="0.01"
                min="0"
                value={value}
                onChange={(e) => setValue(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && addFixedExpense()}
              />
            </FormGroup>
          </FormGrid>

          <ButtonGroup>
            <Button
              $variant="primary"
              onClick={addFixedExpense}
              disabled={isAdding}
              $block
            >
              {isAdding ? "Adicionando..." : "➕ Adicionar"}
            </Button>
          </ButtonGroup>
        </FormCard>

        {/* Lista de Gastos Fixos */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
        >
          <ListHeader>
            <ListTitle>
              💼 Gastos Fixos
            </ListTitle>
            <ItemCount>
              {fixedList.length} itens
            </ItemCount>
          </ListHeader>

          {renderList()}
        </motion.div>
      </motion.div>
    </Container>
  );
}
